mapper.select:
SELECT COUNT(*)
FROM cloud_computing_course a
LEFT JOIN cloud_computing_class b ON a.ID = b.course_id
WHERE a.id = #{CourseId}
  AND a.teacher_id = #{UserId}

SELECT COUNT(*)
FROM cloud_computing_course a
LEFT JOIN cloud_computing_class b ON a.ID = b.course_id
LEFT JOIN cloud_computing_class_student c ON c.class_id = b.ID
WHERE a.id = #{CourseId}
  AND a.teacher_id = #{UserId}
